package com.tekwatt.reporting.dto;import com.tekwatt.reporting.entity.*;import java.time.Instant;import java.util.UUID;public record ReportResponse(UUID id,UUID tenantId,ReportType reportType,ReportFormat format,ReportStatus status,Instant from,Instant to,String fileName,String errorMessage,Instant createdAt,Instant completedAt){public static ReportResponse from(Report r){return new ReportResponse(r.getId(),r.getTenantId(),r.getReportType(),r.getReportFormat(),r.getStatus(),r.getPeriodFrom(),r.getPeriodTo(),r.getFileName(),r.getErrorMessage(),r.getCreatedAt(),r.getCompletedAt());}}
